import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"From Preview to Production","description":"","frontmatter":{},"headers":[],"relativePath":"en/getting-started/preview-production.md","filePath":"en/getting-started/preview-production.md","lastUpdated":1794405696000}`),a={name:`en/getting-started/preview-production.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="from-preview-to-production" tabindex="-1">From Preview to Production <a class="header-anchor" href="#from-preview-to-production" aria-label="Permalink to “From Preview to Production”">​</a></h1><p>When you update the system, deploy to a preview environment, verify it there, and release only the approved commit to production. This is a system-update procedure, separate from a campaign&#39;s &quot;draft → start delivery&quot;.</p><h2 id="how-preview-and-production-differ" tabindex="-1">How Preview and production differ <a class="header-anchor" href="#how-preview-and-production-differ" aria-label="Permalink to “How Preview and production differ”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Preview</th><th>Production</th></tr></thead><tbody><tr><td>URL and passkeys</td><td>A fixed preview origin</td><td>The production origin</td></tr><tr><td>Database, users, campaigns</td><td>The preview D1</td><td>The production D1</td></tr><tr><td>Durable Objects</td><td>Preview only</td><td>Production only</td></tr><tr><td>Access</td><td>Limited to approved people</td><td>Follows your operating policy</td></tr><tr><td>Jev</td><td>A fixed stub in the initial setup</td><td>Real judgments with the production key</td></tr></tbody></table><p>If you use site-only Jev keys, keep the <a href="./../operations/jev-keys">JEV_KEYRING</a> for Preview and Production independent. Don&#39;t copy ciphertext, keys or usage records into production.</p><p>This uses Cloudflare Worker Previews. A Version URL shares production resources, so it can&#39;t replace this separated check.</p><h2 id="_1-build-the-preview-version" tabindex="-1">1. Build the preview version <a class="header-anchor" href="#_1-build-the-preview-version" aria-label="Permalink to “1. Build the preview version”">​</a></h2><p>Commit your settings and code, and make the tests pass.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:cloudflare</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf:preview</span></span></code></pre></div><p>The script verifies that the database, migration target, rate-limit namespace and authentication settings differ from production. It migrates and deploys to Preview only, and stores the commit and Deployment ID in <code>data/deployments/preview.json</code>.</p><p>Use the fixed Preview URL. Don&#39;t use an individual Deployment URL as the place to register passkeys.</p><h2 id="_2-check-it" tabindex="-1">2. Check it <a class="header-anchor" href="#_2-check-it" aria-label="Permalink to “2. Check it”">​</a></h2><ul><li>Enter through Access, and confirm passkey registration and signing in again.</li><li>Switch between sites and check permissions.</li><li>Check saving a campaign draft, starting delivery and stopping it.</li><li>Check the display and shared design on the same-origin demo page.</li><li>Note the preview commit shown at the top of the screen.</li></ul><p>Don&#39;t treat the stub&#39;s 0.95 as a measurement from Jev or as campaign effect. Check the real model separately, after setting a key and a cost budget.</p><p>An SDK on an external site can&#39;t talk without an authentication cookie to an API that Access protects entirely. The current private Preview uses the same-origin demo. For testing with an external site, design the protection scope of the admin console and the delivery API separately.</p><h2 id="_3-release-the-approved-version-to-production" tabindex="-1">3. Release the approved version to production <a class="header-anchor" href="#_3-release-the-approved-version-to-production" aria-label="Permalink to “3. Release the approved version to production”">​</a></h2><p>Run this <strong>only after the check is finished and the production release has been explicitly approved</strong>.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf:release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reviewed-commit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FULL_40_CHARACTER_COMMIT_SHA</span></span></code></pre></div><p>It compares the hashes of HEAD, the working tree, the deployment record and the Production settings, and stops if there are unchecked or uncommitted changes. Specify the full 40-character SHA, not a short 7-character one.</p><p>The preview database, accounts, passkeys and campaigns are not copied to production. Production uses its own data and is registered for the first time on the production origin.</p><h2 id="notes-when-updating" tabindex="-1">Notes when updating <a class="header-anchor" href="#notes-when-updating" aria-label="Permalink to “Notes when updating”">​</a></h2><p>This repository&#39;s CI only runs checks. <code>cf:deploy</code> also requires the same check and stops without a deployment record. If Cloudflare Builds or another external CI runs <code>wrangler deploy</code> directly, it skips this check, so turn off automatic production deployment and unify on manual releases. Changing the code alone does not disconnect an external service&#39;s integration.</p><p>In a new working environment with no deployment record, redeploy the same commit to Preview to recreate the record and the check. If you test several branches at once, separate the Preview name, D1, origin and migration settings for each.</p><p>For production backups and rollback, see <a href="./../operations/maintenance">updates and recovery</a>.</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};